body.script:
//
var VNX_CONFIG = {
  productLabel: 'Sản phẩm',   // nhãn dùng cho bài giới thiệu phần mềm
  productCount: 6,            // số sản phẩm hiện trên trang chủ
  relatedCount: 3             // số bài liên quan dưới mỗi bài
};
(function(){
  var home = location.protocol + '//' + location.host + '/';
  function esc(s){return String(s||'').replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];});}
  function bigThumb(u){
    if(!u) return '';
    return u.replace(/\/s\d+(-[a-z0-9-]+)?\//,'/w640-h360-p-k-no-nu/').replace(/=s\d+(-[a-z0-9-]+)?$/,'=w640-h360-p-k-no-nu');
  }
  function feed(label, n, cb){
    var url = home + 'feeds/posts/summary' + (label ? '/-/' + encodeURIComponent(label) : '') + '?alt=json&max-results=' + n;
    fetch(url).then(function(r){return r.json();}).then(function(d){cb((d.feed && d.feed.entry) || []);}).catch(function(){cb([]);});
  }
  function card(e, badge){
    var link = '', i;
    for(i=0;i<e.link.length;i++){ if(e.link[i].rel==='alternate'){ link=e.link[i].href; } }
    var title = e.title.$t;
    var img = e.media$thumbnail ? bigThumb(e.media$thumbnail.url) : '';
    var sum = (e.summary && e.summary.$t || '').replace(/\s+/g,' ').trim();
    if(sum.length>140) sum = sum.slice(0,140) + '…';
    var d = new Date(e.published.$t);
    var date = ('0'+d.getDate()).slice(-2)+'/'+('0'+(d.getMonth()+1)).slice(-2)+'/'+d.getFullYear();
    return '<article class="card"><a class="card-thumb" href="'+esc(link)+'">' +
      (img ? '<img loading="lazy" alt="'+esc(title)+'" src="'+esc(img)+'"/>' : '<span class="thumb-ph">VNX</span>') +
      (badge ? '<span class="badge">'+esc(badge)+'</span>' : '') +
      '</a><div class="card-body"><h3 class="card-title"><a href="'+esc(link)+'">'+esc(title)+'</a></h3>' +
      '<p class="card-snip">'+esc(sum)+'</p><div class="card-meta"><span>'+date+'</span><a class="more" href="'+esc(link)+'">Xem &#8594;</a></div></div></article>';
  }

  // Lưới sản phẩm trên trang chủ
  var box = document.getElementById('vnx-products');
  if(box){
    feed(VNX_CONFIG.productLabel, VNX_CONFIG.productCount, function(list){
      if(!list.length){ box.innerHTML = '<div class="status-msg">Chưa có sản phẩm. Hãy đăng bài và gắn nhãn <b>'+esc(VNX_CONFIG.productLabel)+'</b>.</div>'; return; }
      box.innerHTML = list.map(function(e){return card(e,'Phần mềm');}).join('');
    });
  }

  // Bài liên quan
  var rel = document.getElementById('vnx-related');
  if(rel){
    var cur = (rel.getAttribute('data-url')||'').replace(/^https?:/,'');
    feed(rel.getAttribute('data-label'), VNX_CONFIG.relatedCount + 1, function(list){
      list = list.filter(function(e){
        return !e.link.some(function(l){return l.rel==='alternate' && l.href.replace(/^https?:/,'')===cur;});
      }).slice(0, VNX_CONFIG.relatedCount);
      if(!list.length){ rel.style.display='none'; return; }
      rel.querySelector('.grid').innerHTML = list.map(function(e){return card(e);}).join('');
    });
  }

  // Nút sao chép cho khối code
  document.querySelectorAll('.post-body pre').forEach(function(pre){
    var b = document.createElement('button');
    b.className='copy-btn'; b.type='button'; b.textContent='Sao chép';
    b.onclick=function(){
      var t = pre.innerText.replace(/Sao chép$|Đã chép ✓$/,'');
      navigator.clipboard && navigator.clipboard.writeText(t.trim()).then(function(){b.textContent='Đã chép ✓';setTimeout(function(){b.textContent='Sao chép';},1500);});
    };
    pre.appendChild(b);
  });

  // Sao chép link bài
  var cp = document.getElementById('copyLink');
  if(cp){ cp.onclick=function(){ navigator.clipboard && navigator.clipboard.writeText(cp.getAttribute('data-url')).then(function(){cp.textContent='Đã chép ✓';}); }; }

  // Menu di động
  var tg = document.getElementById('navToggle'), nav = document.getElementById('nav');
  if(tg && nav){ tg.onclick=function(){ nav.classList.toggle('open'); }; }

  // Nút lên đầu trang + năm
  var top = document.getElementById('toTop');
  window.addEventListener('scroll', function(){ top.classList.toggle('show', window.scrollY > 600); }, {passive:true});
  top.onclick=function(){ window.scrollTo(0,0); };
  var y = document.getElementById('vnx-year'); if(y) y.textContent = new Date().getFullYear();
})();
//
